/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Float, piHexDigits, pprintUseUnicode, rational } from '../../src';
import { text } from '../sympy-str';

describe("doctests of sympy.ntheory.bbp_pi", () => {
  it("pi_hex_digits(0)", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(piHexDigits(rational(0)))).toBe('3243f6a8885a30');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
  it("pi_hex_digits(0, 3)", () => {
    const unicode = pprintUseUnicode(false);
    try {
      expect(text(piHexDigits(rational(0), rational(3)))).toBe('324');
    } finally {
      pprintUseUnicode(unicode);
    }
  });
});

